// ServUO: Services/Revamped Dungeons/BlackthornDungeon/Creatures/AgentoftheCrown.cs (cc-P196; the display list
// generated by gen_agent.py, notes). The Agent of the Crown, "Minax Artifact Turn in Officer" (1154517): a turn-in
// NPC (Mobiles/NPCs/BaseTurnInMobile.cs) who takes artifacts bearing the crest of Minax (MinaxArtifacts.IsMinax,
// ServUO reads ReforgedSuffix.Minax off the four equipment bases) for one Blackthorn point each
// (BlackthornData.AwardPoints) and opens the Blackthorn reward gump. His pack holds one of each of the 136 crest
// items, unmovable, exactly as ServUO packs them: the reward gump finds the matching item there and shows the real
// properties under each reward (BaseRewardGump: Owner.Backpack.FindItemByType, AddItemProperty).
//
// Spawned by [GenBlackthorn in nine Felucca cities and in the Trammel castle (BlackthornSpawns, ServUO
// RevampedSpawns/BlackthornDungeonAgent.xml). The clothes are ours through the SetWearable extension (cc-P194).

using System;
using ModernUO.Serialization;
using Server.Engines.Points;
using Server.Gumps;
using Server.Items;
using Server.Mobiles;

namespace Server.Engines.Blackthorn;

[SerializationGenerator(0, false)]
public partial class AgentOfTheCrown : BaseTurnInMobile
{
    public override int TitleLocalization => 1154520;  // Click a minor artifact to turn in for reward points.
    public override int CancelLocalization => 1154519; // Bring me items bearing the crest of Minax and I will reward you with valuable items.
    public override int TurnInLocalization => 1154571; // Turn In Minax Artifacts
    public override int ClaimLocalization => 1154572;  // Claim Blackthorn Artifacts

    [Constructible]
    public AgentOfTheCrown() : base("the Agent Of The Crown")
    {
    }

    public override void InitBody()
    {
        base.InitBody();

        Name = NameList.RandomName("male");

        Hue = Race.Human.RandomSkinHue();
        Body = 0x190;
        HairItemID = 0x2047;
        HairHue = 0x46D;
    }

    public override void InitOutfit()
    {
        this.SetWearable(new ChainChest(), 2106);
        this.SetWearable(new ThighBoots(), 2106);
        this.SetWearable(new Obi(), 1775);
        this.SetWearable(new BodySash(), 1775);
        this.SetWearable(new GoldRing());
        this.SetWearable(new Epaulette()); // Items/Equipment/Clothing/Epaulette.cs, a leaf port for him

        foreach (var type in DisplayTypes)
        {
            if (Activator.CreateInstance(type) is Item item)
            {
                item.Movable = false;
                PackItem(item);
            }
        }
    }

    public override void GetProperties(IPropertyList list)
    {
        base.GetProperties(list);

        list.Add(1154517); // Minax Artifact Turn in Officer
    }

    public override void AwardPoints(PlayerMobile pm, Item item, int amount)
    {
        MinaxArtifacts.Remove(item);
        BlackthornData.Instance.AwardPoints(pm, amount);
    }

    public override bool IsRedeemableItem(Item item) => MinaxArtifacts.IsMinax(item);

    public override void SendRewardGump(Mobile m)
    {
        if (m is PlayerMobile pm && m.Player && m.CheckAlive())
        {
            m.SendGump(new BlackthornRewardGump(this, pm));
        }
    }

